def check_args(args, schema):
    """Return a list of error strings for a tool call's arguments; an empty list means they are valid.

    Checks the subset a tool schema uses: required properties, a type per property ("string", "integer",
    "number", "boolean"), enum values, and additionalProperties: false.
    """
    types = {"string": str, "integer": int, "number": (int, float), "boolean": bool}
    errors = []
    props = schema.get("properties", {})
    for name in schema.get("required", []):
        if name not in args:
            errors.append(f"missing {name}")
    for name, value in args.items():
        spec = props.get(name)
        if spec is None:
            continue
        if not isinstance(value, types[spec["type"]]):
            errors.append(f"{name}: wrong type")
        elif "enum" in spec and value not in spec["enum"]:
            errors.append(f"{name}: not in enum")
    return errors

